def changed_paths(before, after):
    def _diff(b, a, prefix):
        paths = set()
        for key in set(b.keys()) | set(a.keys()):
            path = f"{prefix}.{key}" if prefix else key
            if key not in b:
                paths.add(path)
            elif key not in a:
                paths.add(path)
            else:
                bv, av = b[key], a[key]
                if isinstance(bv, dict) and isinstance(av, dict):
                    paths |= _diff(bv, av, path)
                elif bv != av:
                    paths.add(path)
        return paths

    return sorted(_diff(before, after, ""))
