from copy import deepcopy


def merge(base, overlay):
    """Recursively merge two JSON-like dictionaries into a deep-independent result.

    Overlay values replace base values. When both corresponding values are dicts,
    they are merged recursively. Lists, scalars, and None from overlay replace
    the base value entirely. A None value in overlay does not delete the key;
    it simply becomes the resulting value.

    Neither input is mutated, and the returned dict shares no nested references
    with either input.
    """
    result = {}

    for key, value in base.items():
        if key in overlay:
            overlay_val = overlay[key]
            if isinstance(value, dict) and isinstance(overlay_val, dict):
                result[key] = merge(value, overlay_val)
            else:
                result[key] = deepcopy(overlay_val)
        else:
            result[key] = deepcopy(value)

    for key, value in overlay.items():
        if key not in base:
            result[key] = deepcopy(value)

    return result
```

