def flatten(value):
    """Flatten a nested dictionary with string keys into dot-separated keys.

    - Non-empty dicts are recursed into.
    - Empty dicts are stored as {} at their path.
    - Lists and scalars are stored as-is.
    - Does not mutate the input.
    """
    result = {}
    _flatten(value, "", result)
    return result


def _flatten(d, prefix, result):
    for key, val in d.items():
        new_key = prefix + "." + key if prefix else key
        if isinstance(val, dict):
            if val:
                _flatten(val, new_key, result)
            else:
                result[new_key] = {}
        else:
            result[new_key] = val
```

