def normalize(path: str) -> str:
    """Normalize an absolute POSIX-like path.

    Collapses repeated slashes, removes '.' components, and resolves
    '..' without going above the root. Returns '/' for the root and
    never includes a trailing slash otherwise.

    Raises ValueError if path is not absolute.
    """
    if not path.startswith('/'):
        raise ValueError(f"not an absolute path: {path!r}")

    stack: list[str] = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        elif part == '..':
            if stack:
                stack.pop()
            # else: already at root, ignore
        else:
            stack.append(part)

    return '/' + '/'.join(stack) if stack else '/'
```

