def pack(items, max_bytes):
    """Greedily pack consecutive items into lists whose total UTF-8 byte
    length does not exceed max_bytes."""
    if not isinstance(max_bytes, int) or max_bytes < 1:
        raise ValueError("max_bytes must be an integer >= 1")

    for item in items:
        if len(item.encode("utf-8")) > max_bytes:
            raise ValueError(
                f"item {item!r} does not fit within {max_bytes} bytes"
            )

    if not items:
        return []

    result = []
    current = []
    current_bytes = 0

    for item in items:
        item_bytes = len(item.encode("utf-8"))
        if current_bytes + item_bytes <= max_bytes:
            current.append(item)
            current_bytes += item_bytes
        else:
            result.append(current)
            current = [item]
            current_bytes = item_bytes

    result.append(current)
    return result
```

