def admit(times, limit, window):
    if limit < 1 or window < 1:
        raise ValueError("limit and window must be >= 1")

    result = []
    accepted = []
    left = 0

    for t in times:
        while left < len(accepted) and accepted[left] <= t - window:
            left += 1

        if len(accepted) - left < limit:
            result.append(True)
            accepted.append(t)
        else:
            result.append(False)

    return result
```

